import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.BW2T23B9.js";const b=JSON.parse('{"title":"音频、TTS 与朗读","description":"","frontmatter":{},"headers":[],"relativePath":"guide/audio-and-tts.md","filePath":"guide/audio-and-tts.md","lastUpdated":1787830168000}'),i={name:"guide/audio-and-tts.md"};function o(l,t,n,h,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="音频、tts-与朗读" tabindex="-1">音频、TTS 与朗读 <a class="header-anchor" href="#音频、tts-与朗读" aria-label="Permalink to &quot;音频、TTS 与朗读&quot;">​</a></h1><p>Turna 区分运行时 TTS 与预录听力资产。单词和短表达优先使用系统 TTS；长对话和听力节目使用 bundle 内 MP3。</p><h2 id="音频来源" tabindex="-1">音频来源 <a class="header-anchor" href="#音频来源" aria-label="Permalink to &quot;音频来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>适用内容</th><th>网络要求</th></tr></thead><tbody><tr><td>系统 / Google TTS</td><td>单词、短表达、卡片文本降级</td><td>取决于设备语音包</td></tr><tr><td>预录 MP3</td><td>对话、长短语、听力阶段</td><td>无</td></tr><tr><td>Anki 媒体</td><td>导入卡片中的音频</td><td>导入后本地</td></tr></tbody></table><p>Android 优先使用 <code>com.google.android.tts</code>，目标语言码为 <code>tr</code>。项目不捆绑离线神经 TTS 模型。</p><h2 id="语言检测" tabindex="-1">语言检测 <a class="header-anchor" href="#语言检测" aria-label="Permalink to &quot;语言检测&quot;">​</a></h2><p>智能朗读按脚本推断 BCP-47 基础语言码。Han、Kana、Hangul、Cyrillic、Arabic、Thai、Devanagari、Greek 和 Hebrew 有明确分支。土耳其语特有字符 <code>ğ ı ş İ</code> 提供强信号；普通 Latin 文本使用课程母语配置回退。</p><p><code>ç ö ü</code> 不单独判定为土耳其语，因为其它欧洲语言也使用这些字符。</p><h2 id="触发点" tabindex="-1">触发点 <a class="header-anchor" href="#触发点" aria-label="Permalink to &quot;触发点&quot;">​</a></h2><ul><li>词汇和表达的手动朗读。</li><li>选择题选项点击时的自动朗读。</li><li>Anki 翻牌前后朗读。</li><li>听力 Interaction 播放。</li><li>原 Anki 音频缺失时的文本 TTS。</li></ul><p>每课程可分别设置自动朗读和母语语言。已知目标语的调用点直接使用目标语言，不重复检测。</p><h2 id="无障碍覆盖" tabindex="-1">无障碍覆盖 <a class="header-anchor" href="#无障碍覆盖" aria-label="Permalink to &quot;无障碍覆盖&quot;">​</a></h2><p>开启 <code>sensoryReduce</code> 后，音效和触觉反馈提前返回。该设置不应删除音频文件，也不修改课程内容。用户主动触发的必要语音与装饰性音效应保持可区分。</p><h2 id="故障处理" tabindex="-1">故障处理 <a class="header-anchor" href="#故障处理" aria-label="Permalink to &quot;故障处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>检查</th></tr></thead><tbody><tr><td>无声音</td><td>系统媒体音量、TTS 引擎、语言包、sensoryReduce</td></tr><tr><td>发音语言错误</td><td>当前课程母语设置、文本脚本、目标语言标记</td></tr><tr><td>Anki 音频缺失</td><td>媒体导入记录、文件名、卡片字段引用</td></tr><tr><td>听力课空白</td><td><code>audioAsset</code>、bundle 声明、资产清单</td></tr><tr><td>播放被截断</td><td>连续触发、页面离开、系统音频焦点</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/authoring/audio-assets">音频资产</a></li><li><a href="/docs/guide/accessibility">可访问性</a></li><li><a href="/docs/guide/interaction-types">交互题型</a></li></ul>',17)])])}const T=a(i,[["render",o]]);export{b as __pageData,T as default};
